mkdir -p /app/bs && cat > /app/bs/model.py <<'EOF'
import numpy as np, itertools, json, sys
N=6
def places(L):
    out=[]
    for r in range(N):
        for c in range(N):
            if c+L<=N: out.append((0,frozenset((r,c+i) for i in range(L))))
            if r+L<=N: out.append((1,frozenset((r+i,c) for i in range(L))))
    return out
P=[places(4),places(3),places(2)]
def nb(s):
    return {(r+dr,c+dc) for r,c in s for dr in(-1,0,1) for dc in(-1,0,1)}
def edge(s): return any(r in(0,5) or c in(0,5) for r,c in s)
center={(2,2),(2,3),(3,2),(3,3)}
lays=[];rules=[]
for a in P[0]:
  for b in P[1]:
    if a[1]&b[1]: continue
    for c in P[2]:
      if (a[1]|b[1])&c[1]: continue
      ss=[a[1],b[1],c[1]]
      t=[ (ss[i]&nb(ss[j])!=set()) for i,j in [(0,1),(0,2),(1,2)]]
      notouch=not any(t)
      par=a[0]==b[0]==c[0]
      bor=all(edge(s) for s in ss)
      cc=not any(s&center for s in ss)
      t01,t02,t12=t
      clus=(t01 or t02) and (t01 or t12) and (t02 or t12)
      g=np.zeros(36,bool)
      for s in ss:
        for r,cc_ in s: g[r*6+cc_]=1
      lays.append(g); rules.append([1,notouch,par,bor,cc,clus])
G=np.array(lays);R=np.array(rules,float)
names=["any","no_touch","parallel","border","center_clear","clustered"]
print(len(G),R.sum(0))
np.savez("/app/bs/lay.npz",G=G,R=R)
EOF
cd /app/bs && python3 model.py

