arguments.command:
cat > post.py <<'EOF'
import numpy as np, json, sys
d=np.load("lay.npz");G=d["G"].astype(float);R=d["R"]
n=R.sum(0);names=["any","no_touch","parallel","border","center_clear","clustered"]
W=R/n/6  # joint (layout, rule)
obs=json.load(open("obs.json")) if len(sys.argv)<2 or True else []
def lik_fire(i,res):
    p=np.where(G[:,i]==1,0.9,0.1); return p if res==1 else 1-p
rowc=np.stack([G.reshape(-1,6,6).sum(2)[:,k] for k in range(6)])
colc=np.stack([G.reshape(-1,6,6).sum(1)[:,k] for k in range(6)])
def scanlik(cnt,rep):
    out=np.zeros_like(cnt,float)
    for dlt,p in[(-1,.15),(0,.7),(1,.15)]:
        out+=p*(np.clip(cnt+dlt,0,6)==rep)
    return out
def post(obs):
    L=np.ones(len(G))
    for o in obs:
        if o[0]=="fire": L*=lik_fire(o[1]*6+o[2],o[3])
        else:
            cnt=(rowc if o[1]=="row" else colc)[o[2]]; L*=scanlik(cnt,o[3])
    J=W*L[:,None]; J/=J.sum(); return J
def H(J):
    pr=J.sum(0); pl=J.sum(1); occ=pl@G
    occ=np.clip(occ,1e-12,1-1e-12)
    hr=-(pr[pr>0]*np.log(pr[pr>0])).sum()/np.log(6)
    hc=-(occ*np.log(occ)+(1-occ)*np.log(1-occ)).sum()/20.1236
    return (hr+hc)/2
def summary(J):
    pr=J.sum(0);occ=J.sum(1)@G
    return pr,occ.reshape(6,6)
def best(J):
    pl=J.sum(1);h0=H(J);res=[]
    for i in range(36):
        eg=0
        for r in(0,1):
            lk=lik_fire(i,r);pz=(pl*lk).sum()
            J2=J*lk[:,None];J2/=J2.sum();eg+=pz*H(J2)
        res.append(((h0-eg)/1,"fire",i//6,i%6))
    for ax,C in(("row",rowc),("col",colc)):
        for k in range(6):
            eg=0
            for rep in range(7):
                lk=scanlik(C[k],rep);pz=(pl*lk).sum()
                if pz<1e-12: continue
                J2=J*lk[:,None];J2/=J2.sum();eg+=pz*H(J2)
            res.append(((h0-eg)/2,"scan",ax,k))
    res.sort(reverse=True);return h0,res[:6]
if __name__=="__main__":
    J=post(obs);pr,occ=summary(J)
    print(dict(zip(names,pr.round(3))));print(occ.round(2))
    print(best(J))
EOF
echo '[]'>obs.json; python3 post.py

